function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

const errorFormatters: Record<string, (error: ErrorObject, path: string) => string> = {
  required: error => {
    const params = error.params as unknown as Record<string, unknown>;
    const missingField = params?.missingProperty;
    return `field '${missingField}' is required`;
  },
  type: (error, path) => {
    const params = error.params as unknown as Record<string, unknown>;
    const expectedType = params?.type;
    return `field '${path}' must be of type ${expectedType}`;
  },
  enum: (error, path) => `field '${path}' must match one of the allowed values`,
};

function formatValidationErrors(errors: ErrorObject[]): string {
  if (errors.length === 0) return 'Input validation failed';

  const messages = errors.map(error => {
    const path = error.dataPath?.startsWith('.') ? error.dataPath.slice(1) : error.dataPath || 'root';
    const formatter = errorFormatters[error.keyword];
    return formatter ? formatter(error, path) : `field '${path}' failed validation: ${error.keyword}`;
  });

  return `Input validation failed: ${messages.join('; ')}`;
}

